function OverseaRenovaTagCell:InitShow()
    KTool.SetActive(self.controller.gameObject,true)
    self:SetTagStatus(false)
end

function OverseaRenovaTagCell:SetTagStatus(state)
    KTool.SetActive(self.Select.gameObject,state)
    KTool.SetActive(self.BtnNotSelect.gameObject,not state)
