function OverseaRenovaTagCell:SetData(data,callBack)
    self.data = data
    self.callBack = callBack
    self:SetSuitBtn()
    self:RefreshShow()
end

function OverseaRenovaTagCell:RefreshShow()
    CfUtils.SetActive(self.ImgPreferential,self.data.isSuit)
    CfUtils.SetActive(self.ImgSelPreferential,self.data.isSuit)
    if self.data.isSuit then
        CfUtils.FillText(self.TextDesc,self.data.name)
        CfUtils.FillImage(self.ImgSelIcon,self.data.photoId)
        self:SetRedGoStatus(false)
    else
        CfUtils.FillImage(self.ImgTagIcon,self.data.photoId)
        CfUtils.FillText(self.OtherDesc,self.data.name)
        CfUtils.FillImage(self.ImgOtherTagIcon,self.data.photoId)
        self:RefreshNewTag()
    end
end

function OverseaRenovaTagCell:RefreshNewTag()
    if self.data.isSuit then return end
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local isHaveRedPoint = maidCoffeeComponent:IsShowAvatarsNewByType(self.data.furnitureType)
    self:SetRedGoStatus(isHaveRedPoint)
end


function OverseaRenovaTagCell:SetRedGoStatus(status)
    KTool.SetActive(self.NoSelectNew.gameObject,status)
    KTool.SetActive(self.SelectNew.gameObject,status)
end

function OverseaRenovaTagCell:SetSuitBtn()
    KTool.SetActive(self.Suit.gameObject,self.data.isSuit)
    KTool.SetActive(self.Others.gameObject,not self.data.isSuit)
end

